export function solveSudoku(board: number[][]): boolean {
    const findEmptySquare = (board: number[][]): [number, number] => {
        for (let i = 0; i < 9; i++) {
            for (let j = 0; j < 9; j++) {
                if (board[i][j] === 0) {
                    return [i, j];
                }
            }
        }
        return [0, 0];
    };

    const validNumber = (value: number, row: number, col: number, board: number[][]): boolean => {
        for (let k = 0; k < 9; k++) {
            if (board[row][k] === value || board[k][col] === value) {
                return false;
            }
        }

        const startX = Math.floor(row / 3) * 3, startY = Math.floor(col / 3) * 3;
        for (let i = 0; i < 3 && i + startX < 9; i++) {
            for (let j = 0; j < 3 && j + startY < 9; j++) {
                if (board[startX + i][startY + j] === value) {
                    return false;
                }
            }
        }

        return true;
    };

    const backtrack = (board: number[][]): boolean => {
        const [row, col] = findEmptySquare(board);
        if (!row || !col) {
            return true;
        }

        for (let value = 1; value <= 9; value++) {
            if (validNumber(value, row, col, board)) {
                board[row][col] = value;
                if (backtrack(board)) {
                    return true;
                }
                board[row][col] = 0;
            }
        }
        return false;
    };

    clearBoard(board);
    backtrack(board);

    return true;
}

export function clearBoard(board: number[][]): void {
    for (let i = 0; i < 9; i++) {
        for (let j = 0; j < 9; j++) {
            board[i][j] = 0;
        }
    }
}

import { solveSudoku, clearBoard } from '../core-engine/core-engine.ts';

export function render(container: HTMLElement): void {
    container.innerHTML = `
        <div class="sudoku-board" id="sudokuBoard"></div>
        <div class="puzzle-input">
            <input type="file" id="puzzleFile" accept=".csv,.txt" multiple>
            <textarea id="puzzleText" placeholder="Enter Sudoku puzzle here"></textarea>
            <button id="loadPuzzle">Load Puzzle</button>
            <div class="step-counters">
                <div class="step-counter" id="stepCounter">Steps: 0</div>
                <div class="step-counter" id="stepCounter2">Backtracks: 0</div>
            </div>
        </div>
    `;

    const boardContainer = document.getElementById('sudokuBoard') as HTMLDivElement;
    const fileInput = document.createElement('input');
    fileInput.type = 'file';
    fileInput.accept = '.csv,.txt';
    fileInput.multiple = true;
    fileInput.id = 'puzzleFile';
    fileInput.addEventListener('change', handleFileInput);
    boardContainer.appendChild(fileInput);

    const textArea = document.createElement('textarea');
    textArea.id = 'puzzleText';
    textArea.placeholder = 'Enter Sudoku puzzle here';
    textArea.addEventListener('input', handleTextInput);
    boardContainer.appendChild(textArea);

    const loadButton = document.createElement('button');
    loadButton.id = 'loadPuzzle';
    loadButton.textContent = 'Load Puzzle';
    loadButton.addEventListener('click', handleLoadPuzzle);
    boardContainer.appendChild(loadButton);

    const stepCounters = document.querySelectorAll('.step-counter');
    stepCounters.forEach((counter) => {
        counter.textContent = 'Steps: 0';
    });

    function handleFileInput(event: Event): void {
        const files = (event.target as HTMLInputElement).files;
        if (!files) return;
        const csv = new Blob([files[0].text], { type: 'text/csv' });
        const board = parseCSV(csv);
        renderBoard(board);
    }

    function handleTextInput(event: Event): void {
        const text = (event.target as HTMLTextAreaElement).value;
        const board = parseText(text);
        renderBoard(board);
    }

    function handleLoadPuzzle(event: Event): void {
        const fileInput = document.getElementById('puzzleFile') as HTMLInputElement;
        if (!fileInput.files) return;
        const file = fileInput.files[0];
        if (file.type !== 'text/csv' && file.type !== 'text/plain') {
            alert('Please select a CSV or text file.');
            return;
        }
        const reader = new FileReader();
        reader.onload = () => {
            const csv = reader.result as string;
            const board = parseCSV(csv);
            renderBoard(board);
        };
        reader.readAsText(file);
    }

    function parseCSV(csv: string): number[][] {
        const rows = csv.split('\n');
        const board = Array(9).fill(undefined).map(() => Array(9).fill(0));
        for (let i = 0; i < 9; i++) {
            for (let j = 0; j < 9; j++) {
                const value = parseInt(rows[i][j], 10);
                if (!isNaN(value)) {
                    board[i][j] = value;
                }
            }
        }
        return board;
    }

    function parseText(text: string): number[][] {
        const lines = text.split('\n');
        const board = Array(9).fill(undefined).map(() => Array(9).fill(0));
        for (let i = 0; i < 9; i++) {
            const line = lines[i];
            if (line) {
                for (let j = 0; j < 9; j++) {
                    const value = parseInt(line[j], 10);
                    if (!isNaN(value)) {
                        board[i][j] = value;
                    }
                }
            }
        }
        return board;
    }

    function renderBoard(board: number[][]): void {
        const boardContainer = document.getElementById('sudokuBoard') as HTMLDivElement;
        boardContainer.innerHTML = '';
        for (let i = 0; i < 9; i++) {
            for (let j = 0; j < 9; j++) {
                const cell = document.createElement('div');
                cell.className = 'sudoku-cell';
                cell.textContent = board[i][j] + '';
                cell.addEventListener('click', () => {
                    const value = prompt('Enter number (1-9):');
                    if (value) {
                        const num = parseInt(value, 10);
                        if (!isNaN(num) && num >= 1 && num <= 9) {
                            board[i][j] = num;
                        }
                    }
                });
                boardContainer.appendChild(cell);
            }
        }
    }
}

