export function handleInput(board: number[][]): boolean {
    const solveSudoku = (b: number[][]) => {
        const findEmpty = (b: number[][]) => b.find((row, i) => row.find((_, j) => !b[i][j])) || [0, 0];
        const validNum = (v: number, r: number, c: number, b: number[][]) => {
            for (let k = 0; k < 9; k++) if (b[r][k] === v || b[k][c] === v) return false;
            const s = 3, startR = Math.floor(r / s) * s, startC = Math.floor(c / s) * s;
            for (let ir = 0; ir < s; ir++) for (let ic = 0; ic < s; ic++) if (b[startR + ir][startC + ic] === v) return false;
            return true;
        };
        const backtrack = (b: number[][]) => {
            const [row, col] = findEmpty(b);
            if (!row) return true;
            for (let v = 1; v <= 9; v++) if (validNum(v, row, col, b)) {
                b[row][col] = v;
                if (backtrack(b)) return true;
                b[row][col] = 0;
            }
            return false;
        };
        return backtrack(b);
    };
    return solveSudoku(board);
}

