export function saveBoard(board: number[][]): void {
    const serialized = JSON.stringify(board);
    localStorage.setItem('sudoku-board', serialized);
    sessionStorage.setItem('sudoku-board', serialized);
}

export function loadBoard(): number[][] {
    const saved = localStorage.getItem('sudoku-board');
    if (saved) return JSON.parse(saved);
    const session = sessionStorage.getItem('sudoku-board');
    if (session) return JSON.parse(session);
    return Array.from({ length: 9 }, () => Array(9).fill(0));
}

